<template>
  <div class="table-container col-sm-12 col-md-12 col-lg-12 min-height-300">
    <div class="row q-mb-sm" style="display: flex">
      <q-card class="q-pa-md q-mb-md" v-if="max_value != 0">
        <div>
          <q-circular-progress
            show-value
            class="text-grey-8 doc-create-file-progress"
            :value="value"
            :min="min_value"
            :max="max_value"
            size="60px"
            color="green"
            track-color="grey-4"
          >
            {{ value }}
            <q-tooltip>Total Sample Documents</q-tooltip>
          </q-circular-progress>
        </div>
      </q-card>

      <q-card
        class="col-5 q-px-md q-mb-md q-ml-lg"
        style="width: 43.8%"
        v-if="max_value != 0"
      >
        <div class="text-center q-my-sm">
          <span class="text-primary text-subtitle1 text-weight-bold"
            >Import Sample Documents</span
          >
        </div>
        <q-select
          v-model="language_origin"
          dense
          outlined
          :options="language_origin_list"
          @update:model-value="uploadFile"
          :label="$t('amount_date_format')"
          :error-message="$t('field_required')"
          :error="origin_error"
        >
          <template v-slot:option="scope">
            <q-item v-bind="scope.itemProps">
              <q-item-section>
                <q-item-label>{{ scope.opt.label }}</q-item-label>
                <q-tooltip v-if="scope.opt.description">
                  <span v-html="scope.opt.description"></span
                ></q-tooltip>
              </q-item-section>
            </q-item>
          </template>
        </q-select>
      </q-card>

      <q-card
        flat
        class="col-5 q-pa-md q-mb-md q-ml-auto float-right"
        v-if="max_value != 0"
      >
        <div
          style="border: 1px dashed"
          class="full-width"
          @drop="drop"
          @dragover="allowDrop"
          @dragleave="dragLeave"
        >
          <div class="text-center q-my-sm">
            <span class="text-subtitle1 text-weight-bold">Drag & Drop</span>
            <br />
            <span class="text-body2">your files here</span>
          </div>
        </div>

        <div style="margin-top: 1rem" class="full-width">
          <q-file
            multiple
            outlined
            v-model="uploadedFiles"
            @update:model-value="uploadFile"
            :label="$t('upload')"
            class="select-field"
            style="width: 100% !important; margin: auto; white-space: nowrap"
            data-cy="upload-multiple-docs"
          >
            <template v-slot:prepend>
              <q-icon name="attachment" />
            </template>
            <template v-slot:file="{ file }">
              <div class="text-white">{{ file.name }}</div>
              <q-tooltip>{{ file.name }}</q-tooltip>
            </template>
          </q-file>
        </div>
      </q-card>

      <!-- From Doc type Settings -->
      <div class="col-auto q-mr-auto" v-if="max_value == 0">
        <div class="q-btn highlighted-back text-center count-card q-mr-sm">
          <div>{{ value }}</div>
          <div>{{ $t('trained_sample') }}</div>
        </div>

        <div
          v-if="total_exported"
          class="q-btn highlighted-back text-center count-card q-mr-sm"
        >
          <div>{{ total_exported }}</div>
          <div>{{ $t('trained_exported') }}</div>
        </div>

        <div
          v-if="total_trained_by_org"
          class="q-btn highlighted-back text-center count-card width-156 q-mr-sm"
        >
          <div>{{ total_trained_by_org }}</div>
          <div>{{ $t('trained_company') }}</div>
        </div>

        <div
          v-if="total_trained"
          class="q-btn highlighted-back text-center count-card q-mr-sm"
        >
          <div>{{ total_trained }}</div>
          <div>{{ $t('trained_overall') }}</div>
        </div>
      </div>

      <div class="col-auto float-right q-ml-auto">
        <div class="row">
          <div v-if="max_value == 0" class="col-auto">
            <UploadTrainingFile
              :doc_type="doc_type"
              :doc_type_key="doc_type_key"
              :re_train="false"
              :language_origin_list="language_origin_list"
              :training_doc_limit="max_value"
            />
          </div>

          <div class="col-auto">
            <TestTrainingFile
              :doc_type="doc_type"
              :doc_type_key="doc_type_key"
              :re_train="false"
              :list_data="list_data"
              :training_doc_limit="max_value"
            />
          </div>
        </div>
      </div>
    </div>

    <div class="relative-position">
      <DocBitsTable
        :rows="rows"
        :columns="columns"
        row-key="id"
        table-id="training_list_table"
        :loading="loading"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        no-data-label="no_record_found"
        flat-style
        table-height="calc(100vh - 590px)"
        @row-action="onRowAction"
      />

      <q-inner-loading :showing="loading" style="z-index: 10">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </div>
  </div>
</template>

<script lang="ts">
import axios from 'axios';
import { objLen } from 'src/utils/general';
import helperMixin from 'src/mixins/helperMixin';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken } from 'pages/APIs';
import { defineComponent, ref, type PropType } from 'vue';
import { notify } from 'src/components/notifications/notify';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import TestTrainingFile from 'src/pages/Settings/Components/ModelTraining/TestTrainingFile.vue';
import UploadTrainingFile from 'src/pages/Settings/Components/ModelTraining/UploadTrainingFile.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';
import {
  getOrgId,
  addOrgIdQueryString,
} from 'src/utils/organization/org_id_helper';

export default defineComponent({
  mixins: [helperMixin],
  components: {
    UploadTrainingFile,
    TestTrainingFile,
    DocBitsTable,
  },
  props: {
    total_exported: {
      type: String,
      default: '',
    },
    total_trained_by_org: {
      type: String,
      default: '',
    },
    total_trained: {
      type: String,
      default: '',
    },
    doc_type: {
      type: String,
      default: '',
    },
    doc_type_key: {
      type: String,
      default: '',
    },
    max_value: {
      type: Number,
      default: 0,
    },
    language_origin_list: {
      type: Array,
      default: () => [],
    },
    list_data: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
  },
  watch: {
    list_data: {
      deep: true,
      handler: function (newVal, oldVal) {
        setTimeout(() => {
          this.prepareRows(newVal);
          this.fileProgress();
        }, 0);
      },
    },
  },
  data() {
    return {};
  },
  mounted: function () {
    this.prepareRows(this.list_data);
    this.fileProgress();
    this.prepareColumns();
  },
  methods: {
    uploadFile() {
      try {
        const origin = this.getOrigin();
        if (!this.uploadedFiles || this.uploadedFiles.length === 0) {
          // notify.error(this.$t('NO_FILE_SELECTED'));
          return;
        }
        this.uploadToServer(this.uploadedFiles);
      } catch (err: any) {
        logError(err);
      } finally {
        //  this.hideLoading();
      }
    },
    async uploadToServer(files: any) {
      try {
        this.showLoading();

        const origin = this.getOrigin();

        let formData = new FormData();

        let invalidFileCounter = 0;
        for (let file of files) {
          if (file.type === 'application/pdf') {
            formData.append('files', file);
          } else {
            invalidFileCounter++;
          }
        }

        if (invalidFileCounter > 0) {
          // throw { message: invalidFileCounter + ' ' + this.$t('INVALID_FILES')};
          throw { message: this.$t('INVALID_FILES') };
        }

        formData.append('doc_locale', origin);
        formData.append('doc_type', this.doc_type_key);
        formData.append('org_id', getOrgId());
        let invoice_response: any;

        let token: string = await getAuthorizationToken();
        invoice_response = await axios.post(
          api.add_sample_document_trainer,
          formData,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
              Authorization: token,
            },
          },
        );
        this.uploadedFiles = [];

        if (invoice_response.data.success === false) {
          logError(invoice_response.data);
          throw { message: this.$t('DOC_UPLOAD_ERROR') };
        } else if (
          invoice_response.data.already_existing_documents &&
          invoice_response.data.already_existing_documents.length > 0
        ) {
          notify.error(
            invoice_response.data.already_existing_documents.length +
              this.$t('messages_ALREADY_UPLOADED'),
          );
        } else if (invoice_response.data.success === true) {
          notify.success(this.$t('DOC_UPLOAD'));
        }

        this.$forceUpdate();
        this.triggerRefreshEvent();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    triggerRefreshEvent() {
      const event = new CustomEvent('refresh_sample_data', { detail: {} });
      document.dispatchEvent(event);
    },
    getOrigin() {
      let origin = '';
      this.origin_error = false;
      if (this.language_origin === null || objLen(this.language_origin) == 0) {
        this.origin_error = true;
        throw 'Please Select Origin';
      }

      if (this.language_origin['locale']) {
        let locale = this.language_origin['locale'] as string;
        origin = locale.substring(0, 5);
      }

      if (origin.length == 0) {
        this.origin_error = true;
        throw 'Please Select Origin';
      }

      return origin;
    },
    allowDrop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.add('bg-grey-5');
      event.currentTarget.classList.add('bd-shadow');
    },
    drop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
      this.uploadedFiles = event.dataTransfer.files;
      this.uploadFile();
    },
    dragLeave(event: any) {
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
    },
    prepareColumns() {
      this.columns = [
        { name: 'name', label: 'Name', field: 'name', align: 'left' },
      ] as UnifiedTableColumn[];
    },
    onRowAction(payload: { action: string; rowId: string; row: any }) {
      if (payload.action === 'delete') {
        const index = this.rows.findIndex((r: any) => r.id === payload.row.id);
        if (index !== -1) {
          this.handleDelete(payload.row, index);
        }
      }
    },

    prepareRows(data: any) {
      this.columns_list = {} as { [k: string]: any };
      const newRows: dynamicObj[] = [];
      for (let [, col] of Object.entries(data)) {
        const column = col as dynamicObj;
        const newRow: dynamicObj = { ...column };
        newRow['name'] = column.sample_file_name;
        newRows.push(newRow);
      }
      this.rows = newRows;
    },
    async handleDelete(row: any, index: number) {
      try {
        if (row.id === '') {
          return;
        }
        this.loading = true;
        let response: any;
        let token: string = await getAuthorizationToken();
        response = await axios.delete(
          addOrgIdQueryString(
            api.delete_sample_document_trainer + '/' + row.id,
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (
          response.data &&
          response.data.hasOwnProperty('success') &&
          response.data.success === false
        ) {
          throw response;
        }

        const event = new CustomEvent('sample_file_delete', { detail: row.id });
        document.dispatchEvent(event);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    fileProgress() {
      this.value = this.rows.length;
    },
  },
  setup() {
    const filter = ref('');
    let data: any = [];
    let model: { [k: string]: any } = {};
    const columns = ref([] as UnifiedTableColumn[]);

    const rowActions: RowActionItem[] = [
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative' },
    ];

    return {
      columns,
      filter,
      rows: ref(data),
      uploadedFiles: ref<File[]>([]),
      language_origin: ref(null),
      origin_error: ref(false),
      loading: ref(false),
      columns_list: ref(model),
      selected: ref(data),
      min_value: ref(0),
      value: ref(0),
      rowActions,
    };
  },
});
</script>

