<!--vbase-->
<template>
  <f-btn
    icon="file_upload"
    style="margin-right: 10px; margin-left: 10px"
    @click="
      multiUploaderDialog = true;
      uploadedFiles = null;
      language_origin = null;
    "
    :label="$t('import_type')"
  />

  <!-- MultiUploader DIALOG STARTS -->

  <q-dialog v-model="multiUploaderDialog" persistent>
    <q-card style="width: 800px; max-width: 80vw">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">
            {{ $t('heading1') }}
          </span>
          {{ $t('heading2') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <!-- <div class="row reverse	">
         <q-btn
          @click="uploadFile"
          color="primary"
          :label="$t('upload')"
        ></q-btn>
        </div> -->

        <div class="row q-ml-auto q-mr-auto" style="width: 300px">
          <q-select
            v-model="language_origin"
            outlined
            style="width: 380px"
            :options="language_origin_list"
            @update:model-value="uploadFile"
            :label="$t('amount_date_format')"
            :error-message="$t('field_required')"
            :error="origin_error"
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label>{{ scope.opt.label }}</q-item-label>
                  <q-tooltip v-if="scope.opt.description">
                    <span v-html="scope.opt.description"></span
                  ></q-tooltip>
                </q-item-section>
              </q-item>
            </template>
            <template v-slot:after>
              <q-icon
                size="md"
                name="info"
                :color="language_origin ? 'primary' : 'grey'"
                class="secondary-c-text cursor-pointer"
              >
                <q-tooltip>
                  <span
                    v-if="language_origin"
                    v-html="language_origin.description"
                  ></span>
                  <span v-else>
                    {{ $t('amounts_dates_format') }}
                  </span>
                </q-tooltip>
              </q-icon>
            </template>
          </q-select>
        </div>

        <div
          class="drag-area text-center full-width"
          style="padding: 20px"
          id="box-droppable"
          @drop="drop"
          @dragover="allowDrop"
          @dragleave="dragLeave"
        >
          <Icon icon="mdi:export" width="64" height="64" />
          <div style="padding: 20px">{{ $t('land_dragndrop') }}</div>
          <q-file
            style="width: 43% !important; margin: auto; white-space: nowrap"
            class="select-field"
            outlined
            multiple
            :model-value="uploadedFiles as any"
            @update:model-value="
              (val) => {
                uploadedFiles = val as any;
                processUploadFiles(val);
              }
            "
            :label="$t('upload')"
          >
            <template v-slot:prepend>
              <q-icon name="attach_file" />
            </template>
            <template v-slot:file="{ index, file }">
              <div class="text-white">
                {{ file.name }}
              </div>
              <q-tooltip>
                {{ file.name }}
              </q-tooltip>
              <span v-if="false"> {{ index }} </span>
            </template>
          </q-file>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <!-- MultiUploader DIALOG END -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import axios from 'axios';
import { objLen } from 'src/utils/general';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    doc_type: {
      type: String,
      default: '',
    },
    doc_type_key: {
      type: String,
      default: '',
    },
    training_doc_limit: {
      type: Number,
      default: 0,
    },
    re_train: {
      type: Boolean,
    },
    language_origin_list: {
      type: Array,
      default: () => [],
    },
  },
  watch: {},
  
  data() {
    return {};
  },
  methods: {
    processUploadFiles(value: any) {
      this.uploadedFiles = value;
      this.uploadFile();
    },
    uploadFile() {
      try {
        const origin = this.getOrigin();
        if (!this.uploadedFiles) {
          // notify.error(this.$t('NO_FILE_SELECTED'));
          return;
        }
        this.uploadToServer(this.uploadedFiles);
      } catch (err: any) {
        logError(err);
      } finally {
        //  this.hideLoading();
      }
    },
    allowDrop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.add('bg-grey-5');
      event.currentTarget.classList.add('bd-shadow');
    },
    drop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
      this.uploadedFiles = event.dataTransfer.files;
      this.uploadFile();
    },
    dragLeave(event: any) {
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
    },
    async uploadToServer(files: any) {
      try {
        this.showLoading();

        this.multiUploaderDialog = false;

        const origin = this.getOrigin();

        let formData = new FormData();

        let invalidFileCounter = 0;
        for (let file of files) {
          if (file.type === 'application/pdf') {
            formData.append('files', file);
          } else {
            invalidFileCounter++;
          }
        }

        if (invalidFileCounter > 0) {
          // throw { message: invalidFileCounter + ' ' + this.$t('INVALID_FILES')};
          throw { message: this.$t('INVALID_FILES') };
        }

        formData.append('doc_locale', origin);
        formData.append('doc_type', this.doc_type_key);
        formData.append('org_id', getOrgId());
        let invoice_response: any;

        let token: string = await getAuthorizationToken();
        invoice_response = await axios.post(
          api.add_sample_document_trainer,
          formData,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
              Authorization: token,
            },
          },
        );
        this.uploadedFiles = '';

        if (invoice_response.data.success === false) {
          logError(invoice_response.data);
          throw { message: this.$t('DOC_UPLOAD_ERROR') };
        } else if (
          invoice_response.data.already_existing_documents &&
          invoice_response.data.already_existing_documents.length > 0
        ) {
          throw {
            message:
              invoice_response.data.already_existing_documents.length +
              this.$t('messages_ALREADY_UPLOADED'),
          };
        } else if (invoice_response.data.success === true) {
          throw { message: this.$t('DOC_UPLOAD') };
        }

        this.$forceUpdate();
        this.triggerRefreshEvent();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    getOrigin() {
      let origin = '';
      this.origin_error = false;
      if (this.language_origin === null || objLen(this.language_origin) == 0) {
        this.origin_error = true;
        throw 'Please Select Origin';
      }

      if (this.language_origin['locale']) {
        let locale = this.language_origin['locale'] as string;
        origin = locale.substring(0, 5);
      }

      if (origin.length == 0) {
        this.origin_error = true;
        throw 'Please Select Origin';
      }

      return origin;
    },
    triggerRefreshEvent() {
      const event = new CustomEvent('refresh_sample_data', { detail: {} });
      document.dispatchEvent(event);
    },
  },
  setup() {
    return {
      multiUploaderDialog: ref(false),
      uploadedFiles: ref(''),
      language_origin: ref(null),
      origin_error: ref(false),
    };
  },
});
</script>

