<!--vbase-->
<template>
  <div align="center">
    <f-btn
      class="q-mb-md"
      :blocked="list_data.length < 10 && training_doc_limit !== 0"
      @click="trainModel"
      :loading="loading"
      loadinglabel="Loading..."
      :label="$t('train_model')"
    >
      <template v-slot:loading>
        <q-spinner-hourglass color="white" />
      </template>
    </f-btn>
    <f-btn
      class="q-ml-sm q-mb-md"
      :disable="list_data.length < 10 && training_doc_limit !== 0"
      @click="
        multiUploaderDialog = true;
        uploadedFiles = null;
        resetTestResults();
      "
      :label="$t('test_classification')"
    />
  </div>

  <!-- MultiUploader DIALOG STARTS -->

  <q-dialog v-model="multiUploaderDialog" persistent>
    <q-card style="min-width: 50%">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">
            {{ $t('test_classification') }}
          </span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <div class="row">
          <div class="col-12">
            <div
              class="drag-area text-center full-width q-mb-md"
              id="box-droppable"
              @drop="drop"
              @dragover="allowDrop"
              @dragleave="dragLeave"
            >
              <Icon icon="mdi:export" width="64" height="64" />
              <div class="q-mb-md">{{ $t('land_dragndrop') }}</div>
              <q-file
                style="width: 50%; margin: auto; white-space: nowrap"
                outlined
                class="select-field"
                multiple
                @update:model-value="uploadFile"
                v-model="uploadedFiles"
                :label="$t('upload')"
              >
                <template v-slot:prepend>
                  <q-icon name="attach_file" />
                </template>
                <template v-slot:file="{ index, file }">
                  <div class="text-white">
                    {{ file.name }}
                  </div>
                  <q-tooltip>
                    {{ file.name }}
                  </q-tooltip>
                  <span v-if="false"> {{ index }} </span>
                </template>
              </q-file>
            </div>
          </div>
        </div>

        <template v-if="test_results_doc_type !== ''">
          <div class="row">
            <div class="col-12">
              <div class="text-center full-width">
                <span class="text-weight-bold">Status: </span>
                <span class="q-ml-md">
                  <template v-if="test_results_doc_type == doc_type">
                    <q-badge color="green" text-color="white" label="Success" />
                  </template>
                  <template v-else>
                    <q-badge color="red" text-color="white" label="Failed" />
                  </template>
                </span>
              </div>
            </div>
          </div>
          <template v-if="test_results_doc_type == doc_type">
            <div class="row">
              <div class="col-12">
                <div class="text-center full-width">
                  <span class="text-weight-bold">Doc Type:</span>
                  <span class="q-ml-md">{{ test_results?.doc_type }}</span>
                </div>
              </div>
            </div>

            <div class="row">
              <div class="col-12">
                <div class="full-width flex flex-center">
                  <span class="text-weight-bold">Doc Type Score:</span>
                  <span class="q-ml-md">{{ docTypeScoreLabel }}</span>
                </div>
              </div>
            </div>

            <div class="row">
              <div class="col-12">
                <div class="text-center full-width">
                  <span class="text-weight-bold">Doc Locale:</span>
                  <span class="q-ml-md">{{ test_results?.doc_locale }}</span>
                </div>
              </div>
            </div>

            <div class="row">
              <div class="col-12">
                <div class="text-center full-width">
                  <span class="text-weight-bold">Doc Locale Score:</span>
                  <span class="q-ml-md">{{ docLocaleScoreLabel }}</span>
                </div>
              </div>
            </div>
          </template>
        </template>
      </q-card-section>

      <q-inner-loading :showing="processing_classification" class="z-index-1">
        <q-spinner-hourglass color="primary" size="6em" />
      </q-inner-loading>
    </q-card>
  </q-dialog>

  <!-- MultiUploader DIALOG END -->
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { api, getAuthorizationToken } from 'pages/APIs';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import axios from 'axios';
import {
  getOrgId,
  addOrgIdQueryString,
} from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
    props: {
    doc_type: {
      type: String,
      default: '',
    },
    doc_type_key: {
      type: String,
      default: '',
    },
    training_doc_limit: {
      type: Number,
      default: 0,
    },
    list_data: [] as any,
  },
  watch: {},
  
  data() {
    return {};
  },
  mounted() {
    this.resetTestResults();
  },
  methods: {
    uploadFile(value: any) {
      this.uploadedFiles = value;
      let file = this.uploadedFiles;
      if (!file) {
        notify.error(this.$t('NO_FILE_SELECTED'));
      }
      this.uploadToServer(file);
    },
    allowDrop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.add('bg-grey-5');
      event.currentTarget.classList.add('bd-shadow');
    },
    drop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');

      this.uploadToServer(event.dataTransfer.files);
    },
    dragLeave(event: any) {
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
    },

    resetTestResults() {
      this.test_results_doc_type = 'INVOICE';
      this.test_results = {
        doc_type: 'INVOICE',
        doc_type_score: 0.9687122862,
        doc_type_classification_method: 'tfidf',
        doc_locale: 'de_DE',
        doc_locale_score: 0.9687122862,
      } as any;
      this.test_results_doc_type = '';
      this.test_results = {} as any;
    },

    async uploadToServer(files: any) {
      try {
        this.processing_classification = true;
        this.resetTestResults();
        this.uploadedFiles = null;
        let formData = new FormData();
        for (let file of files) {
          formData.append('file', file);
        }
        formData.append('org_id', getOrgId());
        let invoice_response: any;
        let token: string = await getAuthorizationToken();
        invoice_response = await axios.post(api.test_classification, formData, {
          headers: {
            'Content-Type': 'multipart/form-data',
            Authorization: token,
          },
        });

        if (invoice_response.data.success === false) {
          throw { message: 'DOC_UPLOAD_ERROR' };
        }

        this.test_results_doc_type = invoice_response.data.data.doc_type;
        this.test_results = invoice_response.data.data;
        this.doc_type_score = invoice_response.data.data.doc_type_score;
        this.doc_locale_score = invoice_response.data.data.doc_locale_score;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing_classification = false;
      }
    },
    async trainModel() {
      try {
        this.loading = true;
        await this.reTrainModel();
        notify.success(
          this.$t('MODEL_TRAINED_SUCCESSFULLY'),
        );

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async reTrainModel() {
      let invoice_response: any;
      let formData = new FormData();
      formData.append('org_id', getOrgId());
      let token: string = await getAuthorizationToken();
      invoice_response = await axios.post(api.retrain_model, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: token,
        },
      });

      if (invoice_response.data.success === false) {
        logError(invoice_response.data);
        throw { message: this.$t('DOC_UPLOAD_ERROR') };
      }
    },
  },
  computed: {
    docTypeScoreLabel: function () {
      return (this.doc_type_score * 100).toFixed(0) + '%';
    },
    docLocaleScoreLabel: function () {
      return (this.doc_locale_score * 100).toFixed(0) + '%';
    },
  },
  setup() {
    return {
      multiUploaderDialog: ref(false),
      uploadedFiles: ref(null),
      loading: ref(false),
      processing_classification: ref(false),
      test_results_doc_type: ref(''),
      test_results: ref({} as any),
      doc_type_score: ref(),
      doc_locale_score: ref(),
      //   test_results: ref({
      // 'doc_type': 'INVOICE',
      // 'doc_type_score': 0.9687122862,
      // 'doc_type_classification_method': 'tfidf',
      // 'doc_locale': 'de_DE',
      // 'doc_locale_score': 0.9687122862
      // } as any),
    };
  },
});
</script>
